import { Prism, languages, insertBefore } from '../prismCore'
import './javascript'

var js = languages.js;
var withId = pattern => RegExp(
	pattern.source.replace(/<ID>/g, '(?!\\d)(?:(?!\\s)[$$\\w\\xA0-\\uFFFF])+')
);

insertBefore('js', 'function-variable', {
	'method-variable': {
		pattern: RegExp('(\\.\\s*)' + js['function-variable'].pattern.source),
		lookbehind: true,
		alias: ['function-variable', 'method', 'function', 'property-access']
	}
});

insertBefore('js', 'function', {
	'method': {
		pattern: RegExp('(\\.\\s*)' + js['function'].source),
		lookbehind: true,
		alias: ['function', 'property-access']
	}
});

insertBefore('js', 'constant', {
	'known-class-name': [
		{
			// standard built-ins
			// https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects
			pattern: /\b(?:(?:Float(?:32|64)|(?:Int|Uint)(?:8|16|32)|Uint8Clamped)?Array|ArrayBuffer|BigInt|Boolean|DataView|Date|Error|Function|Intl|JSON|(?:Weak)?(?:Map|Set)|Math|Number|Object|Promise|Proxy|Reflect|RegExp|String|Symbol|WebAssembly)\b/,
			alias: 'class-name'
		},
		{
			// errors
			pattern: /\b(?:[A-Z]\w*)Error\b/,
			alias: 'class-name'
		}
	]
});

insertBefore('js', 'keyword', {
	'imports': {
		// https://tc39.es/ecma262/#sec-imports
		pattern: withId(/(\bimport\b\s*)(?:<ID>(?:\s*,\s*(?:\*\s*as\s+<ID>|\{[^{}]*\}))?|\*\s*as\s+<ID>|\{[^{}]*\})(?=\s*\bfrom\b)/),
		lookbehind: true,
		inside: js
	},
	'exports': {
		// https://tc39.es/ecma262/#sec-exports
		pattern: withId(/(\bexport\b\s*)(?:\*(?:\s*as\s+<ID>)?(?=\s*\bfrom\b)|\{[^{}]*\})/),
		lookbehind: true,
		inside: js
	}
});

insertBefore('js', 'punctuation', {
	'property-access': {
		pattern: withId(/(\.\s*)#?<ID>/),
		lookbehind: true
	},
	'maybe-class-name': {
		pattern: /(^|[^$\w\xA0-\uFFFF]|\s)[A-Z][$\w\xA1-\uFFFF]+/,
		lookbehind: true
	},
	'dom': {
		// this contains only a few commonly used DOM variables
		pattern: /\b(?:document|(?:local|session)Storage|location|navigator|performance|window)\b/,
		alias: 'variable'
	},
	'console': {
		pattern: /\bconsole(?=\s*\.)/,
		alias: 'class-name'
	}
});

// add 'maybe-class-name' to tokens which might be a class name

['function', 'function-variable', 'method', 'method-variable', 'property-access'].forEach(token => {
	var value = js[token];

	// convert regex to object
	if (value instanceof RegExp) {
		value = js[token] = {
			pattern: value
		};
	}

	// keep in mind that we don't support arrays

	(value.inside ||= {})['maybe-class-name'] = /^[A-Z][\s\S]*/;
})
